% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[{"name":"bisectorRed","hex":"EF6068","reason":"distinguishes the two angle bisectors from the parallelogram sides"}],"reference":"page 8 question 12"}
\begin{tikzpicture}[line width=0.8pt,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{bisectorRed}{HTML}{EF6068}
\coordinate (A) at (0,0);\coordinate (B) at (0.65,1.8);\coordinate (C) at (4.25,1.8);\coordinate (D) at (3.6,0);
\pgfmathsetmacro{\sideLength}{sqrt(0.65*0.65+1.8*1.8)}
\coordinate (X) at ({0.65+\sideLength},1.8);\coordinate (Y) at ({3.6-\sideLength},0);
\draw (A)--(B)--(C)--(D)--cycle;
\draw[bisectorRed,dashed] (A)--(X);\draw[bisectorRed,dashed] (C)--(Y);
\draw[line width=0.4pt,-{Stealth[length=2mm]}] ($(A)!0.44!(B)$)--($(A)!0.56!(B)$);
\draw[line width=0.4pt,-{Stealth[length=2mm]}] ($(D)!0.44!(C)$)--($(D)!0.56!(C)$);
\foreach \t in {0.48,0.53}{\draw[line width=0.4pt,-{Stealth[length=2mm]}] ($(B)!\t!(C)$)--($(B)!{\t+0.045}!(C)$);\draw[line width=0.4pt,-{Stealth[length=2mm]}] ($(A)!\t!(D)$)--($(A)!{\t+0.045}!(D)$);}
\pic[draw,line width=0.4pt,angle radius=5mm] {angle=D--A--X};
\pic[draw,line width=0.4pt,angle radius=5mm] {angle=X--A--B};
\pic[draw,line width=0.4pt,angle radius=5mm] {angle=B--C--Y};
\pic[draw,line width=0.4pt,angle radius=5mm] {angle=Y--C--D};
\pgfmathsetmacro{\theta}{atan2(1.8,0.65)}
\foreach \ang in {\theta/4,3*\theta/4}{\draw[line width=0.4pt] ($(A)+(\ang:0.45)$)--($(A)+(\ang:0.55)$);}
\foreach \ang in {180+\theta/4,180+3*\theta/4}{\foreach \offset in {-2,2}{\draw[line width=0.4pt] ($(C)+({\ang+\offset}:0.45)$)--($(C)+({\ang+\offset}:0.55)$);}}
\node at ($(A)+({\theta/4}:0.76)$) {$\alpha$};\node at ($(A)+({3*\theta/4}:0.76)$) {$\alpha$};
\node at ($(C)+({180+\theta/4}:0.76)$) {$\varphi$};\node at ($(C)+({180+3*\theta/4}:0.76)$) {$\varphi$};
\node[below left] at (A) {$A$};\node[above left] at (B) {$B$};\node[above right] at (C) {$C$};\node[below right] at (D) {$D$};\node[above] at (X) {$X$};\node[below] at (Y) {$Y$};
\end{tikzpicture}
